"""Exact enumeration of plane graphs on convex points and validation vs A054726."""
from __future__ import annotations
from itertools import combinations
from typing import List, Tuple

Chord = Tuple[int, int]


def chords(n: int) -> List[Chord]:
    return [(i, j) for i in range(n) for j in range(i + 1, n)]


def cross(x: Chord, y: Chord) -> bool:
    a, b = x
    c, d = y
    return (a < c < b < d) or (c < a < d < b)


def is_plane(graph: Tuple[Chord, ...]) -> bool:
    return all(not cross(graph[i], graph[j])
               for i in range(len(graph)) for j in range(i + 1, len(graph)))


def num_plane(n: int) -> int:
    cs = chords(n)
    return sum(1 for k in range(len(cs) + 1)
               for s in combinations(cs, k) if is_plane(s))


if __name__ == "__main__":
    ref = [1, 1, 2, 8, 48, 352]
    for n in range(6):
        print(n, num_plane(n), "OK" if num_plane(n) == ref[n] else "FAIL")

"""Triangulation-subset floor L(n,h)=2^(3n-3-h) and its minimization at h=n."""
from __future__ import annotations


def tri_floor(n: int, h: int) -> int:
    return 2 ** (3 * n - 3 - h)


def minimizing_hull_size(n: int) -> int:
    return min(range(3, n + 1), key=lambda h: tri_floor(n, h))


if __name__ == "__main__":
    n = 12
    for h in range(3, n + 1):
        print(f"h={h}: edges={3*n-3-h}, L={tri_floor(n, h)}")
    print("argmin h =", minimizing_hull_size(n), "(= n = convex position)")

